<?php
require_once __DIR__.'/includes/config.php'; require_owner();
$uid=(int)$_SESSION['user_id'];
$from=trim($_GET['from']??date('Y-m-01')); $to=trim($_GET['to']??date('Y-m-d')); $action=trim($_GET['action']??'');
$validDate=fn($d)=>is_string($d)&&preg_match('/^\d{4}-\d{2}-\d{2}$/',$d)&&DateTime::createFromFormat('Y-m-d',$d)?->format('Y-m-d')===$d;
if(!$validDate($from))$from=date('Y-m-01'); if(!$validDate($to))$to=date('Y-m-d');
$where=['user_id=?','DATE(created_at)>=?','DATE(created_at)<=?'];$params=[$uid,$from,$to]; if($action!==''){$where[]='action=?';$params[]=$action;}
$q=$pdo->prepare('SELECT * FROM activity_logs WHERE '.implode(' AND ',$where).' ORDER BY id DESC LIMIT 300');$q->execute($params);$logs=$q->fetchAll();
$aq=$pdo->prepare('SELECT DISTINCT action FROM activity_logs WHERE user_id=? ORDER BY action');$aq->execute([$uid]);$actions=$aq->fetchAll(PDO::FETCH_COLUMN);
$pageTitle='Activity log'; require __DIR__.'/includes/header.php';
?>
<div class="page-heading"><div><div class="text-secondary small">OWNER TOOLS</div><h1 class="h3 fw-bold mb-1">Activity log</h1><p class="muted mb-0">Review recorded actions by owners and staff. New events are logged as each instrumented action succeeds.</p></div></div>
<div class="card mb-4"><div class="card-body"><form class="row g-3 align-items-end"><div class="col-md-3"><label class="form-label">From</label><input class="form-control" type="date" name="from" value="<?=e($from)?>"></div><div class="col-md-3"><label class="form-label">To</label><input class="form-control" type="date" name="to" value="<?=e($to)?>"></div><div class="col-md-4"><label class="form-label">Action</label><select class="form-select" name="action"><option value="">All actions</option><?php foreach($actions as $a):?><option value="<?=e($a)?>" <?=$a===$action?'selected':''?>><?=e(ucwords(str_replace('_',' ',$a)))?></option><?php endforeach;?></select></div><div class="col-md-2 d-flex gap-2"><button class="btn btn-primary">Filter</button><a class="btn btn-outline-secondary" href="activity.php">Reset</a></div></form></div></div>
<div class="card"><div class="card-body"><div class="d-flex justify-content-between align-items-center mb-3"><h2 class="h5 fw-bold mb-0">Recorded events</h2><span class="badge text-bg-light"><?=count($logs)?> events (max 300)</span></div><div class="table-responsive"><table class="table align-middle"><thead><tr><th>Date/time</th><th>Person</th><th>Action</th><th>Item</th><th>Details</th></tr></thead><tbody><?php foreach($logs as $l):?><tr><td class="text-nowrap"><?=e(date('d M Y H:i:s',strtotime($l['created_at'])))?></td><td><?=e($l['actor_name'])?><div class="small text-secondary"><?=e(ucfirst($l['actor_type']))?></div></td><td><span class="badge text-bg-light"><?=e(ucwords(str_replace('_',' ',$l['action'])))?></span></td><td><?=e($l['entity_type']?:'—')?><?=$l['entity_id']?' #'.(int)$l['entity_id']:''?></td><td><?=e($l['details']?:'—')?></td></tr><?php endforeach;?></tbody></table><?php if(!$logs):?><div class="empty-state">No activity matched these filters. New supported actions will appear here after the Phase 6 migration.</div><?php endif;?></div></div></div>
<?php require __DIR__.'/includes/footer.php'; ?>
